<script lang="ts">import Shell from '$lib/components/Shell.svelte';import {CheckCircle2,CircleDashed,FileJson} from 'lucide-svelte';let {data}=$props();const d=$derived(data.snapshot);const hasTruth=$derived(d.evaluation.driftrecon.truthCount>0);const rows:Array<[string,string,string,string,boolean]>=[['Predicted relationships','Active edges from this run','predictedCount','int',false],['Human review count','Open exceptions routed to a person','humanReviewCount','int',false],['Residual amount','Σ unexplained payout differences','residualAmount','money',false],['Precision','Correct ÷ predicted','precision','ratio',true],['Recall','Correct ÷ true relationships','recall','ratio',true],['Payout coverage','Explained payouts ÷ payouts','payoutCoverage','ratio',true],['False auto-match count','Incorrect automatic relationships','falseAutoMatchCount','int',true],['False auto-match rate','Incorrect automatic ÷ automatic','falseAutoMatchRate','ratio',true],['Autonomous coverage','Correct auto value ÷ total value','autonomousReconciliationCoverage','ratio',true]];function fmt(v:number,k:string){if(k==='ratio')return `${(v*100).toFixed(1)}%`;if(k==='money')return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(v/100);return String(v)}</script>
<Shell><div class="eval"><header class="page-head"><div><h1>Evaluation</h1></div><span class="status-pill"><i></i>{hasTruth?`${d.evaluation.driftrecon.truthCount} truth edges`:'No ground truth'}</span></header><div class="score-grid"><article class="card"><span>Precision</span><strong>{d.run&&hasTruth?fmt(d.evaluation.driftrecon.precision,'ratio'):'—'}</strong></article><article class="card"><span>Payout coverage</span><strong>{d.run&&hasTruth?fmt(d.evaluation.driftrecon.payoutCoverage,'ratio'):'—'}</strong></article><article class="card"><span>False auto-matches</span><strong>{d.run&&hasTruth?d.evaluation.driftrecon.falseAutoMatchCount:'—'}</strong></article></div><section class="card table"><header><div><h2>vs baseline</h2></div><div class="badges"><span class="chip">{#if d.run}<CheckCircle2 size={13}/>Run complete{:else}<CircleDashed size={13}/>Not run{/if}</span><span class="chip"><FileJson size={13}/>{hasTruth?'Truth loaded':'No truth'}</span></div></header><table><thead><tr><th>Metric</th><th>Formula</th><th class="right">DriftRecon</th><th class="right">Baseline</th></tr></thead><tbody>{#each rows as row}{@const available=d.run&&(!row[4]||hasTruth)}<tr><td><b>{row[0]}</b></td><td>{row[1]}</td><td class="right mono">{available?fmt(d.evaluation.driftrecon[row[2]],row[3] as string):'—'}</td><td class="right mono">{available?fmt(d.evaluation.baseline[row[2]],row[3] as string):'—'}</td></tr>{/each}</tbody></table></section></div></Shell>
<style>.eval{display:flex;flex-direction:column;gap:24px}.score-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.score-grid article{padding:21px}.score-grid span{font:9px 'DM Mono';text-transform:uppercase;letter-spacing:.11em;color:var(--muted)}.score-grid strong{display:block;margin:11px 0 5px;font:500 29px 'DM Mono'}.table{overflow:hidden}.table>header{padding:18px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line)}.table h2{font-size:15px;margin:0}.badges{display:flex;gap:7px}.badges .chip{font-size:8px}.table td:nth-child(2){color:var(--muted)}.table td b{font-size:12px}@media(max-width:800px){.score-grid{grid-template-columns:1fr}.table>header{align-items:start;flex-direction:column}.badges{flex-wrap:wrap}}</style>
